  1	package perf
  2	
  3	import (
  4		"context"
  5		"fmt"
  6		"log/slog"
  7		"os"
  8		"strconv"
  9		"time"
 10	
 11		"github.com/entireio/cli/cmd/entire/cli/logging"
 12	)
 13	
 14	// SlowSpanEnvVar overrides the slow-root-span threshold, in milliseconds.
 15	// A value of 0 (or a negative one) disables level escalation entirely, so every
 16	// root span logs at DEBUG as it did before.
 17	const SlowSpanEnvVar = "ENTIRE_PERF_SLOW_MS"
 18	
 19	// DefaultSlowSpanThreshold is how long a root span must take before its timing
 20	// tree is logged at WARN instead of DEBUG.
 21	//
 22	// Root spans carry the only per-step breakdown of a hook, and they used to log
 23	// exclusively at DEBUG. Real sessions run at INFO, so a hook that took seconds
 24	// left behind no record of *which* step took them — the one case anybody needs
 25	// the breakdown for. Escalating slow spans means a real session captures its own
 26	// diagnosis without the user reproducing anything or turning on DEBUG.
 27	//
 28	// 1.5s sits above what a healthy hook costs and below the observed slow cluster,
 29	// so fast turns stay silent instead of logging a WARN every turn.
 30	const DefaultSlowSpanThreshold = 1500 * time.Millisecond
 31	
 32	// slowSpanThreshold reports the duration above which a root span is considered
 33	// slow. Invalid values fall back to the default rather than disabling
 34	// escalation, so a typo does not silently switch the diagnostics off.
 35	func slowSpanThreshold() time.Duration {
 36		raw, ok := os.LookupEnv(SlowSpanEnvVar)
 37		if !ok {
 38			return DefaultSlowSpanThreshold
 39		}
 40		ms, err := strconv.Atoi(raw)
 41		if err != nil {
 42			return DefaultSlowSpanThreshold
 43		}
 44		if ms <= 0 {
 45			// Explicit opt-out: never escalate.
 46			return 0
 47		}
 48		return time.Duration(ms) * time.Millisecond
 49	}
 50	
 51	// isSlowSpan reports whether d is long enough to warrant escalating a root
 52	// span's log line from DEBUG to WARN.
 53	func isSlowSpan(d time.Duration) bool {
 54		threshold := slowSpanThreshold()
 55		return threshold > 0 && d >= threshold
 56	}
 57	
 58	// Span tracks timing for an operation and its substeps.
 59	// A Span is not safe for concurrent use from multiple goroutines.
 60	type Span struct {
 61		name       string
 62		start      time.Time
 63		parent     *Span
 64		children   []*Span
 65		duration   time.Duration
 66		attrs      []slog.Attr
 67		ctx        context.Context
 68		ended      bool
 69		err        error
 70		isLoopIter bool
 71	}
 72	
 73	// Start begins a new span. If ctx already has a span, the new one becomes a child.
 74	// Returns the updated context and the span. Call span.End() when the operation completes.
 75	func Start(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *Span) {
 76		parent := spanFromContext(ctx)
 77		s := &Span{
 78			name:   name,
 79			start:  time.Now(),
 80			parent: parent,
 81			attrs:  attrs,
 82			ctx:    ctx,
 83		}
 84		if parent != nil {
 85			parent.children = append(parent.children, s)
 86		}
 87		return contextWithSpan(ctx, s), s
 88	}
 89	
 90	// RecordError marks the span as errored. Only the first non-nil error is stored;
 91	// subsequent calls are no-ops. Call this before End() on error paths.
 92	func (s *Span) RecordError(err error) {
 93		if err == nil || s.err != nil {
 94			return
 95		}
 96		s.err = err
 97	}
 98	
 99	// End completes the span. For root spans, emits a single log line with the full
100	// timing tree -- at DEBUG normally, or at WARN with slow=true when the span
101	// exceeded slowSpanThreshold so the breakdown survives a default-level session.
102	// For child spans, records the duration only.
103	// Safe to call multiple times -- subsequent calls are no-ops.
104	func (s *Span) End() {
105		if s.ended {
106			return
107		}
108		s.ended = true
109		s.duration = time.Since(s.start)
110	
111		// Only root spans emit log output
112		if s.parent != nil {
113			return
114		}
115	
116		logCtx := logging.WithComponent(s.ctx, "perf")
117		attrs := make([]any, 0, 3+len(s.attrs)+countChildStepAttrs(s))
118		attrs = append(attrs, slog.String("op", s.name))
119		attrs = append(attrs, slog.Int64("duration_ms", s.duration.Milliseconds()))
120		if s.err != nil {
121			attrs = append(attrs, slog.Bool("error", true))
122		}
123	
124		// Decide the level before appending the step tree so "slow" sits next to
125		// duration_ms rather than after a long tail of step attrs.
126		slow := isSlowSpan(s.duration)
127		if slow {
128			attrs = append(attrs, slog.Bool("slow", true))
129		}
130	
131		attrs = appendChildStepAttrs(attrs, s, "")
132	
133		for _, a := range s.attrs {
134			attrs = append(attrs, a)
135		}
136	
137		if slow {
138			logging.Warn(logCtx, "perf", attrs...)
139			return
140		}
141		logging.Debug(logCtx, "perf", attrs...)
142	}
143	
144	// appendChildStepAttrs emits the full child timing tree under parent.
145	//
146	// Normal children use their span names, with ~N suffixes for duplicate sibling
147	// names. Loop iterations (from LoopSpan.Iteration) keep the historical numeric
148	// keys: steps.<loopName>.0_ms, steps.<loopName>.1_ms, etc.
149	func appendChildStepAttrs(attrs []any, parent *Span, parentKey string) []any {
150		seen := make(map[string]int, len(parent.children))
151		loopIndex := 0
152		for _, child := range parent.children {
153			if !child.ended {
154				child.End()
155			}
156	
157			var stepKey string
158			if child.isLoopIter && parentKey != "" {
159				stepKey = fmt.Sprintf("%s.%d", parentKey, loopIndex)
160				loopIndex++
161			} else {
162				stepKey = childStepKey(child.name, seen)
163				if parentKey != "" {
164					stepKey = parentKey + "." + stepKey
165				}
166			}
167	
168			attrs = append(attrs, slog.Int64("steps."+stepKey+"_ms", child.duration.Milliseconds()))
169			if child.err != nil {
170				attrs = append(attrs, slog.Bool("steps."+stepKey+"_err", true))
171			}
172	
173			attrs = appendChildStepAttrs(attrs, child, stepKey)
174		}
175		return attrs
176	}
177	
178	func countChildStepAttrs(parent *Span) int {
179		count := 0
180		for _, child := range parent.children {
181			count++
182			if child.err != nil {
183				count++
184			}
185			count += countChildStepAttrs(child)
186		}
187		return count
188	}
189	
190	// childStepKey returns a unique key for a child span name.
191	// First occurrence keeps the original name; subsequent get ~1, ~2, etc.
192	// Uses "~" separator to avoid collision with grandchild "." indexing
193	// (e.g. steps.foo.0_ms for loop iterations).
194	// The seen map is updated in place.
195	func childStepKey(name string, seen map[string]int) string {
196		n := seen[name]
197		seen[name] = n + 1
198		if n == 0 {
199			return name
200		}
201		return fmt.Sprintf("%s~%d", name, n)
202	}
203	
204	// LoopSpan wraps a Span that groups loop iterations. Each call to Iteration
205	// creates a child span representing one pass through the loop.
206	//
207	// Usage:
208	//
209	//	ctx, loop := perf.StartLoop(ctx, "process_sessions")
210	//	for _, item := range items {
211	//	    iterCtx, iterSpan := loop.Iteration(ctx)
212	//	    doWork(iterCtx, item)
213	//	    iterSpan.End()
214	//	}
215	//	loop.End()
216	type LoopSpan struct {
217		span *Span
218	}
219	
220	// StartLoop begins a new loop span. The returned context contains the loop span
221	// and should be passed to Iteration. Call loop.End() after the loop completes.
222	func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
223		ctx, s := Start(ctx, name, attrs...)
224		return ctx, &LoopSpan{span: s}
225	}
226	
227	// Iteration creates a child span for a single loop iteration. The caller must
228	// call End() on the returned span when the iteration completes.
229	func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
230		ctx, s := Start(ctx, l.span.name)
231		s.isLoopIter = true
232		return ctx, s
233	}
234	
235	// End completes the loop span, auto-ending any unended iteration children first
236	// so their durations are captured at loop-end time rather than deferring to the
237	// root span's End() (which may run much later).
238	func (l *LoopSpan) End() {
239		for _, child := range l.span.children {
240			if !child.ended {
241				child.End()
242			}
243		}
244		l.span.End()
245	}

